def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    # If no pairs are possible, still return a valid (empty) PrefBatch.
    if K <= 1 or B == 0:
        empty = objective.new_empty((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'rank_adjacent_pairs'}
        )

    # Deterministic per-instance ranking: lower objective is better.
    order = objective.argsort(dim=1, descending=False)  # (B, K)

    # Build all adjacent pairs in a vectorized way.
    # For each b: winner=order[b, i], loser=order[b, i+1] for i in [0..K-2]
    b_idx = torch.arange(B, device=objective.device, dtype=torch.long).unsqueeze(1).expand(B, K - 1).reshape(-1)
    winner_idx = order[:, :-1].reshape(-1).to(dtype=torch.long)
    loser_idx = order[:, 1:].reshape(-1).to(dtype=torch.long)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={'builder': 'rank_adjacent_pairs'}
    )

def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, N = objective.shape

    max_pairs = extra.get('max_pairs', 128)
    max_pairs_per_instance = extra.get('max_pairs_per_instance', None)

    # Compute per-instance cap without relying on Python int/float casts.
    if B <= 0:
        per_instance_cap = 0
    else:
        per_instance_cap = max_pairs // B
        if per_instance_cap < 1:
            per_instance_cap = 1

    if max_pairs_per_instance is not None and per_instance_cap > max_pairs_per_instance:
        per_instance_cap = max_pairs_per_instance

    if N >= 2 and per_instance_cap > (N - 1):
        per_instance_cap = N - 1

    if B <= 0 or N < 2 or per_instance_cap <= 0:
        empty = objective.new_empty((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'rank_ladder_basic', 'per_instance_cap': per_instance_cap},
        )

    # order: [B, N], best (lowest objective) first.
    order = objective.argsort(dim=1)
    k = per_instance_cap

    winner_idx = order[:, :k].reshape(-1).to(dtype=torch.long)
    loser_idx = order[:, 1:(k + 1)].reshape(-1).to(dtype=torch.long)

    b_idx = torch.arange(B, device=objective.device, dtype=torch.long).unsqueeze(1).expand(B, k).reshape(-1)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={'builder': 'rank_ladder_basic', 'per_instance_cap': per_instance_cap},
    )

